<?php require __DIR__.'/bootstrap.php';$q=trim($_GET['q']??'');$pageTitle='Tìm kiếm · '.setv('site_name','FilmNova');$movies=[];if($q){$s=db()->prepare('SELECT * FROM movies WHERE is_hidden=0 AND (name LIKE ? OR origin_name LIKE ? OR actors LIKE ? OR categories LIKE ?) ORDER BY updated_at DESC LIMIT 100');$l="%$q%";$s->execute([$l,$l,$l,$l]);$movies=$s->fetchAll();}require __DIR__.'/partials/header.php';?><div class="container page"><small>TÌM KIẾM</small><h1><?=e($q?'Kết quả cho “'.$q.'”':'Tìm phim')?></h1><form class="big-search"><input name="q" value="<?=e($q)?>" placeholder="Tên phim, diễn viên, thể loại..."><button class="primary">Tìm</button></form><div class="grid wide"><?php foreach($movies as $m): ?><article><a href="<?=e(site('watch.php?slug='.urlencode($m['slug'])))?>"><div class="poster"><img loading="lazy" src="<?=e(img($m['poster_url']?:$m['thumb_url']))?>" alt="<?=e($m['name'])?>" onerror="this.onerror=null;this.src=''assets/placeholder.svg';"><span><?=e($m['quality']?:'HD')?></span></div><b><?=e($m['name'])?></b><small><?=e($m['origin_name'])?></small></a></article><?php endforeach;?></div><?php if($q&&!$movies): ?><div class="empty">Không tìm thấy phim.</div><?php endif;?></div><?php require __DIR__.'/partials/footer.php';?>
